enum class CacheReplPolicy
{
    LRU,
    SRRIP,
    RAND,
    DRRIP
};

inline constexpr bool repl_uses_set_dueling(CacheReplPolicy p)
{
    return p == CacheReplPolicy::DRRIP;
}

